import 'dart:async';
import 'package:app_links/app_links.dart';
import 'package:flutter/material.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatefulWidget {
  const MyApp({Key? key}) : super(key: key);

  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  // 1. 라우팅을 위한 Navigator Key 정의
  final _navigatorKey = GlobalKey<NavigatorState>();
  // 2. 스트림 구독 관리를 위한 변수
  StreamSubscription<Uri>? _linkSubscription;

  @override
  void initState() {
    super.initState();
    initDeepLinks();
  }

  @override
  void dispose() {
    _linkSubscription?.cancel();
    super.dispose();
  }

  // Deep Link 초기화 및 스트림 리스너 설정 로직 (Step 3에서 구현)
  Future<void> initDeepLinks() async {
    // 구현 예정
  }

  // 링크를 받아 라우팅하는 로직 (Step 4에서 구현)
  void openAppLink(Uri uri) {
    // 구현 예정
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'App Links Demo',
      navigatorKey: _navigatorKey,
      initialRoute: "/",
      // onGenerateRoute는 Step 4에서 상세 구현
      onGenerateRoute: (settings) {
        return MaterialPageRoute(
          builder: (context) => const Scaffold(body: Center(child: Text('Home Screen'))),
          settings: settings,
        );
      },
    );
  }
}

// ... (생략)

Future<void> initDeepLinks() async {
  final appLinks = AppLinks();

  // 1. Cold Start (앱이 완전히 종료된 상태에서 링크를 통해 실행)
  final initialUri = await appLinks.getInitialLink();
  if (initialUri != null) {
    debugPrint('Initial Link: $initialUri');
    openAppLink(initialUri);
  }

  // 2. Hot Start (앱이 실행 중이거나 백그라운드에 있을 때 링크 클릭)
  _linkSubscription = appLinks.uriLinkStream.listen((uri) {
    debugPrint('Stream Link: $uri');
    openAppLink(uri);
  });
}

void openAppLink(Uri uri) {
  // 예제는 URL Fragment (#/book/1)를 라우팅 경로로 사용합니다.
  final routePath = uri.fragment;
  if (routePath.isNotEmpty) {
    // Navigator Key를 사용하여 라우팅 수행
    _navigatorKey.currentState?.pushNamed(routePath);
  } else {
    // Fragment가 없는 경우 기본 경로로 이동
    _navigatorKey.currentState?.pushNamed('/');
  }
}

// ... (생략)

// ... (_MyAppState build 메서드 내부)

@override
Widget build(BuildContext context) {
  return MaterialApp(
    navigatorKey: _navigatorKey,
    initialRoute: "/",
    onGenerateRoute: (RouteSettings settings) {
      Widget routeWidget = defaultScreen();

      final routeName = settings.name;
      if (routeName != null) {
        if (routeName.startsWith('/book/')) {
          // 예: /book/hello-world
          final bookId = routeName.substring(routeName.indexOf('/book/') + 6);
          routeWidget = customScreen(bookId);
        } else if (routeName == '/book') {
          // 예: /book (파라미터 없음)
          routeWidget = customScreen("None");
        }
      }

      return MaterialPageRoute(
        builder: (context) => routeWidget,
        settings: settings,
      );
    },
  );
}

Widget defaultScreen() {
  return Scaffold(
    appBar: AppBar(title: const Text('기본 화면')), 
    body: const Center(
      child: SelectableText('앱이 실행되었습니다. 외부 링크를 클릭하세요.'),
    ),
  );
}

Widget customScreen(String bookId) {
  return Scaffold(
    appBar: AppBar(title: const Text('상세 화면')), 
    body: Center(child: Text('Deep Link로 열린 Book ID: $bookId')),
  );
}
